<?php
namespace App\Http\Controllers;
use App\Services\{AiAgents,AiProvider,VoiceLab};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class AiAgentsController extends Controller {
 private function w(Request $r):int {abort_unless($r->user()?->voice_enabled&&$r->user()->voice_role==='admin'&&$r->user()->voice_workspace_id,403);return $r->user()->voice_workspace_id;}
 public function index(Request $r,AiAgents $s){$w=$this->w($r);return response()->json(['agents'=>DB::table('ai_agents')->where('workspace_id',$w)->latest('updated_at')->get()->map(fn($a)=>$s->present($a)),'defaults'=>AiAgents::defaults(),'languages'=>AiAgents::LANGUAGES,'connection'=>$this->connectionView($r,$w),'queues'=>DB::table('voice_live_queues')->where('workspace_id',$w)->get(['id','name']),'senders'=>DB::table('wa_senders')->where('workspace_id',$w)->get(['id','label','number','provider']),'bindings'=>DB::table('ai_whatsapp_bindings')->where('workspace_id',$w)->get(),'sessions'=>DB::table('ai_sessions')->where('workspace_id',$w)->latest()->limit(30)->get(['id','agent_id','channel','mode','provider','model','status','turns','input_tokens','output_tokens','estimated_usd','summary','created_at']),'sip_bindings'=>DB::table('ai_sip_bindings')->where('workspace_id',$w)->get(['id','agent_id','queue_id','transfer_uri','enabled']),'telephony'=>['ready'=>app(\App\Services\AiSip::class)->ready()]])->header('Cache-Control','no-store, private');}
 private function connectionView(Request $r,int $w):array {$c=app(AiProvider::class)->connection($w);$bridge=app(\App\Services\Portal\TenantBridge::class)->config();$central=(bool)$bridge;$operator=(bool)$r->session()->get('discai_identity.platform_admin',false);$c['managed']=$central;$c['can_configure']=!$central;$c['can_manage_telephony']=!$central||$operator;$c['administration_url']=$operator?config('discai.portal_url').'/ai-administration':null;if($central)unset($c['prices'],$c['project_id'],$c['text_model'],$c['voice_model']);return $c;}
 public function save(Request $r,AiAgents $s,?string $id=null){$d=$r->validate(['config'=>'required|array','revision'=>'sometimes|integer']);return $s->save($this->w($r),$r->user()->id,$d,$id);}
 public function publish(Request $r,AiAgents $s,string $id){$d=$r->validate(['revision'=>'required|integer']);return $s->publish($this->w($r),$r->user()->id,$id,$d['revision']);}
 public function pause(Request $r,AiAgents $s,string $id){$w=$this->w($r);$d=$r->validate(['paused'=>'required|boolean']);$s->row($w,$id);DB::table('ai_agents')->where('id',$id)->update(['paused'=>$d['paused'],'updated_at'=>now()]);app(VoiceLab::class)->audit($w,$r->user()->id,'ai.agent.pause',$id,$d);return $s->present($s->row($w,$id));}
 public function connection(Request $r,AiProvider $p){$w=$this->w($r);abort_if(app(\App\Services\Portal\TenantBridge::class)->config(),403,'A conexão é gerenciada pela administração DiscAI.');$d=$r->validate(['api_key'=>'nullable|string|min:20|max:300','sip_secret'=>['nullable','string','max:300','regex:/^whsec_[A-Za-z0-9+\/=]+$/D'],'project_id'=>['nullable','string','regex:/^proj_[a-zA-Z0-9_-]{1,100}$/D'],'enabled'=>'required|boolean','daily_requests'=>'required|integer|between:1,1000','cost_acknowledged'=>'required|accepted']);$result=$p->save($w,$d);app(VoiceLab::class)->audit($w,$r->user()->id,'ai.connection.configured','openai',['enabled'=>$d['enabled'],'daily_requests'=>$d['daily_requests']]);return $result;}
 public function start(Request $r,AiAgents $s,string $id){$w=$this->w($r);$d=$r->validate(['mode'=>'required|in:local,premium','cost_acknowledged'=>'accepted_if:mode,premium']);$a=$s->start($w,$r->user()->id,$id,$d['mode']);return ['id'=>$a->id,'greeting'=>json_decode($a->config,true)['greeting'],'mode'=>$a->mode];}
 public function turn(Request $r,AiAgents $s,string $id){$w=$this->w($r);$d=$r->validate(['request_id'=>'required|uuid','input'=>'required|string|max:2000']);return $s->turn($w,$id,$d['request_id'],$d['input'],$r->user()->id);}
 public function session(Request $r,AiAgents $s,string $id){$w=$this->w($r);$session=$s->session($w,$id);unset($session->config);return ['session'=>$session,'turns'=>DB::table('ai_turns')->where('session_id',$id)->orderBy('sequence')->orderBy('created_at')->orderBy('id')->get(['id','input','output','status','action','latency_ms','created_at'])];}
 public function voice(Request $r,AiAgents $s,AiProvider $p,string $id){$w=$this->w($r);$d=$r->validate(['sdp'=>'required|string|max:30000','cost_acknowledged'=>'required|accepted']);abort_unless(str_starts_with($d['sdp'],'v=0'),422,'Oferta de áudio inválida.');$session=$s->start($w,$r->user()->id,$id,'premium','voice');try{$response=$p->voice($w,$d['sdp'],$s->voiceConfig(json_decode($session->config,true)));DB::table('ai_sessions')->where('id',$session->id)->update(['provider_call_id'=>$response['call_id']]);return ['id'=>$session->id,'sdp'=>$response['sdp'],'expires_at'=>$session->expires_at,'greeting'=>json_decode($session->config,true)['greeting']];}catch(\Throwable $e){DB::table('ai_sessions')->where('id',$session->id)->update(['status'=>'failed']);throw $e;}}
 public function close(Request $r,AiAgents $s,AiProvider $p,string $id){$w=$this->w($r);$session=$s->session($w,$id,$r->user()->id);$closed=!$session->provider_call_id||$p->hangup($w,$session->provider_call_id);DB::table('ai_sessions')->where('id',$id)->update(['status'=>$closed?'closed':'closing','expires_at'=>now(),'updated_at'=>now()]);return ['closed'=>$closed];}
 public function sip(Request $r,string $id){$w=$this->w($r);abort_if(app(\App\Services\Portal\TenantBridge::class)->config()&&!$r->session()->get('discai_identity.platform_admin',false),403,'A conexão de telefonia é gerenciada pela administração DiscAI.');$d=$r->validate(['queue_id'=>'required|integer','transfer_uri'=>['nullable','string','max:250','regex:~^sips?:[a-zA-Z0-9_.+-]+@[a-zA-Z0-9.-]+(?::[0-9]{1,5})?(?:;transport=tls)?$~D'],'enabled'=>'required|boolean','rotate'=>'sometimes|boolean','cost_acknowledged'=>'required|accepted']);abort_if(str_contains(strtolower($d['transfer_uri']??''),'sip.api.openai.com'),422,'O destino de transferência não pode retornar ao agente de IA.');return app(\App\Services\AiSip::class)->configure($w,$r->user()->id,$id,$d);}
 public function binding(Request $r,AiAgents $s,string $id){$w=$this->w($r);$d=$r->validate(['sender_id'=>'required|integer','enabled'=>'required|boolean','cost_acknowledged'=>'required|accepted']);$s->row($w,$id);DB::table('wa_senders')->where('workspace_id',$w)->where('id',$d['sender_id'])->firstOrFail();if($d['enabled']){$c=$s->published($w,$id);app(AiProvider::class)->textReady($w);abort_unless($c['handoff_queue_id'],422,'Escolha uma fila para os casos que precisam da equipe.');abort_unless(DB::table('ai_sessions')->where('workspace_id',$w)->where('agent_id',$id)->where('mode','premium')->where(function($q)use($w){$provider=app(AiProvider::class)->textProvider($w);$q->where('provider',$provider);if($provider==='openai')$q->orWhereNull('provider');})->where('config',json_encode($c))->where('input_tokens','>',0)->exists(),422,'Conclua um teste de texto com a API antes de ativar no WhatsApp.');}return DB::transaction(function()use($w,$id,$d,$r){DB::table('voice_runtime')->where('id',1)->lockForUpdate()->firstOrFail();$old=DB::table('ai_whatsapp_bindings')->where('sender_id',$d['sender_id'])->first();abort_if($old&&$old->agent_id!==$id&&$old->enabled,409,'Este número já usa outro agente. Desative o vínculo anterior.');DB::table('ai_whatsapp_bindings')->updateOrInsert(['sender_id'=>$d['sender_id']],['workspace_id'=>$w,'agent_id'=>$id,'enabled'=>$d['enabled'],'enabled_at'=>$d['enabled']?now():null,'created_at'=>$old?->created_at??now(),'updated_at'=>now()]);app(VoiceLab::class)->audit($w,$r->user()->id,'ai.whatsapp.binding',$id,$d);return ['ok'=>true];});}
}
